func timeAgo(t time.Time) string {
	if t.IsZero() {
		return "-"
	}
	secs := int(time.Since(t).Seconds())
	switch {
	case secs < 60:
		return "just now"
	case secs < 3600:
		mins := secs / 60
		if mins == 1 {
			return "1 minute ago"
		}
		return fmt.Sprintf("%d minutes ago", mins)
	case secs < 86400:
		hours := secs / 3600
		if hours == 1 {
			return "1 hour ago"
		}
		return fmt.Sprintf("%d hours ago", hours)
	case secs < 2592000:
		days := secs / 86400
		if days == 1 {
			return "yesterday"
		}
		return fmt.Sprintf("%d days ago", days)
	case secs < 31536000:
		months := secs / 2592000
		if months == 1 {
			return "1 month ago"
		}
		return fmt.Sprintf("%d months ago", months)
	default:
		years := secs / 31536000
		if years == 1 {
			return "1 year ago"
		}
		return fmt.Sprintf("%d years ago", years)
	}
}

